-- Banco de preguntas oficial, lote 16. Reejecutable sin duplicados.
BEGIN;
ALTER TABLE public.banco_preguntas ADD COLUMN IF NOT EXISTS "FUENTE" text;
ALTER TABLE public.banco_preguntas ADD COLUMN IF NOT EXISTS "PAGINAS_PDF" text;
WITH payload AS (
  SELECT * FROM jsonb_to_recordset('[{"MATERIA":"BIOLOGIA CELULAR","TEMA":"ciclo celular","DIFICULTAD":"facil","PREGUNTA":"Una célula deja temporalmente de dividirse. ¿En qué estado puede permanecer?","OPCION_A":"En puntos de control como G1 y G2; una lesión también puede detener otras fases.","OPCION_B":"Por fosforilación de Rb a cargo de complejos Cdk-ciclina.","OPCION_C":"En G0, un estado de reposo o quiescencia fuera del ciclo de división activo.","OPCION_D":"En la fase S de la interfase.","RESPUESTA_CORRECTA":"C","EXPLICACION":"En G0, un estado de reposo o quiescencia fuera del ciclo de división activo.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"580–617"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"division celular y muerte programada","DIFICULTAD":"medio","PREGUNTA":"¿Qué resultado esperas de una mitosis de una célula somática?","OPCION_A":"Reduce la dotación cromosómica y genera células haploides.","OPCION_B":"Dos células hijas con la misma dotación cromosómica que la célula de partida.","OPCION_C":"Apoptosis, una forma de muerte celular programada.","OPCION_D":"Dos núcleos hijos con la misma información cromosómica que el núcleo progenitor.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Dos células hijas con la misma dotación cromosómica que la célula de partida.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"618–649"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"division celular y muerte programada","DIFICULTAD":"facil","PREGUNTA":"¿Para qué sirve la meiosis en la formación de gametos?","OPCION_A":"Apoptosis, una forma de muerte celular programada.","OPCION_B":"Reduce la dotación cromosómica y genera células haploides.","OPCION_C":"Dos células hijas con la misma dotación cromosómica que la célula de partida.","OPCION_D":"Reduce la afinidad de la histona por el ADN y abre la cromatina.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Reduce la dotación cromosómica y genera células haploides.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"618–649"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"division celular y muerte programada","DIFICULTAD":"medio","PREGUNTA":"Si una célula se elimina de forma ordenada y controlada, ¿qué proceso ocurre?","OPCION_A":"Apoptosis, una forma de muerte celular programada.","OPCION_B":"Reduce la dotación cromosómica y genera células haploides.","OPCION_C":"Dos células hijas con la misma dotación cromosómica que la célula de partida.","OPCION_D":"Puede bloquear su traducción o favorecer su degradación.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Apoptosis, una forma de muerte celular programada.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"618–649"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"division celular y muerte programada","DIFICULTAD":"facil","PREGUNTA":"¿Qué distingue en general a la necrosis de la apoptosis?","OPCION_A":"La quiescencia puede revertirse; la senescencia bloquea de modo duradero la proliferación.","OPCION_B":"Dos células hijas con la misma dotación cromosómica que la célula de partida.","OPCION_C":"La necrosis suele seguir a un daño externo con ruptura celular; la apoptosis es un programa celular regulado.","OPCION_D":"El cinetocoro se organiza sobre la región centromérica y conecta el cromosoma con el aparato de segregación.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La necrosis suele seguir a un daño externo con ruptura celular; la apoptosis es un programa celular regulado.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"618–649"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"biologia celular del cancer","DIFICULTAD":"medio","PREGUNTA":"¿Qué pasa cuando una célula tumoral deja de obedecer las señales que frenan la división?","OPCION_A":"Continúa avanzando en el ciclo y multiplicándose pese a señales que deberían detenerla.","OPCION_B":"Modificar el microambiente y favorecer el desarrollo de células neoplásicas.","OPCION_C":"Puede mantener la proliferación sin depender de los controles habituales del tejido.","OPCION_D":"Puede proliferar de manera descontrolada, una característica central del cáncer.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Puede proliferar de manera descontrolada, una característica central del cáncer.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"650–696"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"biologia celular del cancer","DIFICULTAD":"facil","PREGUNTA":"¿Qué es la angiogénesis en el crecimiento de un tumor?","OPCION_A":"El que regula proliferación, diferenciación y muerte celular programada.","OPCION_B":"La vía sanguínea, linfática o serosa, según el tipo de tumor.","OPCION_C":"La formación de nuevos vasos sanguíneos que aportan oxígeno y nutrientes al tumor.","OPCION_D":"La respuesta inmunitaria, incluida la acción de linfocitos y células NK.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La formación de nuevos vasos sanguíneos que aportan oxígeno y nutrientes al tumor.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"650–696"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"biologia celular del cancer","DIFICULTAD":"facil","PREGUNTA":"¿Qué significa que un cáncer haya hecho metástasis?","OPCION_A":"Que cambia el uso de nutrientes y energía para sostener su proliferación.","OPCION_B":"Continúa avanzando en el ciclo y multiplicándose pese a señales que deberían detenerla.","OPCION_C":"Que células tumorales se han diseminado y han formado lesiones en otro sitio del organismo.","OPCION_D":"La formación de nuevos vasos sanguíneos que aportan oxígeno y nutrientes al tumor.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Que células tumorales se han diseminado y han formado lesiones en otro sitio del organismo.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"650–696"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"biologia celular del cancer","DIFICULTAD":"facil","PREGUNTA":"¿Cómo contribuye la pérdida de función de un gen supresor tumoral?","OPCION_A":"Permite que sobrevivan células alteradas que normalmente serían eliminadas.","OPCION_B":"Puede proliferar de manera descontrolada, una característica central del cáncer.","OPCION_C":"Elimina un freno normal del crecimiento o de la supervivencia celular.","OPCION_D":"Continúa avanzando en el ciclo y multiplicándose pese a señales que deberían detenerla.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Elimina un freno normal del crecimiento o de la supervivencia celular.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"650–696"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"respuesta inmunitaria","DIFICULTAD":"facil","PREGUNTA":"¿Cuál responde primero de forma general ante muchos microorganismos: la inmunidad innata o la adaptativa?","OPCION_A":"El linfocito B, al convertirse en célula plasmática.","OPCION_B":"La inmunidad innata; actúa con rapidez y reconoce patrones generales.","OPCION_C":"La hebra molde, también llamada antisentido o no codificante.","OPCION_D":"El benigno permanece localizado; el maligno puede invadir tejidos y diseminarse.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La inmunidad innata; actúa con rapidez y reconoce patrones generales.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"697–737"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"respuesta inmunitaria","DIFICULTAD":"facil","PREGUNTA":"¿Qué ventaja aporta la memoria de la inmunidad adaptativa?","OPCION_A":"Activar una respuesta protectora y memoria inmunitaria frente al agente real.","OPCION_B":"Permite generar varias proteínas a partir de una misma región genética.","OPCION_C":"Cambio de un tipo celular diferenciado por otro ante condiciones persistentes.","OPCION_D":"Permite una respuesta más eficaz cuando el organismo vuelve a encontrar el mismo antígeno.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Permite una respuesta más eficaz cuando el organismo vuelve a encontrar el mismo antígeno.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"697–737"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"respuesta inmunitaria","DIFICULTAD":"facil","PREGUNTA":"¿Qué célula puede producir anticuerpos después de activarse y diferenciarse?","OPCION_A":"El linfocito B, al convertirse en célula plasmática.","OPCION_B":"La inmunidad innata; actúa con rapidez y reconoce patrones generales.","OPCION_C":"Activar una respuesta protectora y memoria inmunitaria frente al agente real.","OPCION_D":"La unión estrecha, que sella el espacio entre ellas.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El linfocito B, al convertirse en célula plasmática.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"697–737"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"respuesta inmunitaria","DIFICULTAD":"facil","PREGUNTA":"¿Qué busca una vacuna al presentar antígenos sin causar la enfermedad?","OPCION_A":"Permite una respuesta más eficaz cuando el organismo vuelve a encontrar el mismo antígeno.","OPCION_B":"Alteraciones genéticas y mecanismos de regulación que afectan el funcionamiento celular.","OPCION_C":"Activar una respuesta protectora y memoria inmunitaria frente al agente real.","OPCION_D":"El linfocito B, al convertirse en célula plasmática.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Activar una respuesta protectora y memoria inmunitaria frente al agente real.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"697–737"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"celulas madre y aplicaciones terapeuticas","DIFICULTAD":"medio","PREGUNTA":"¿Qué dos capacidades definen a una célula madre?","OPCION_A":"Tipos celulares derivados de las tres capas embrionarias, pero no tejido placentario por sí solas.","OPCION_B":"Autorrenovarse durante mucho tiempo y diferenciarse hacia células especializadas.","OPCION_C":"Tejidos extraembrionarios, como los de la placenta.","OPCION_D":"Más restringido: genera varios tipos celulares relacionados con el tejido o linaje al que pertenece.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Autorrenovarse durante mucho tiempo y diferenciarse hacia células especializadas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"738–771"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"celulas madre y aplicaciones terapeuticas","DIFICULTAD":"medio","PREGUNTA":"¿Qué puede formar una célula madre totipotente que una pluripotente no forma por sí sola?","OPCION_A":"Autorrenovarse durante mucho tiempo y diferenciarse hacia células especializadas.","OPCION_B":"Tejidos extraembrionarios, como los de la placenta.","OPCION_C":"Tipos celulares derivados de las tres capas embrionarias, pero no tejido placentario por sí solas.","OPCION_D":"Más restringido: genera varios tipos celulares relacionados con el tejido o linaje al que pertenece.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Tejidos extraembrionarios, como los de la placenta.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"738–771"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"celulas madre y aplicaciones terapeuticas","DIFICULTAD":"facil","PREGUNTA":"¿Qué pueden producir las células madre pluripotentes?","OPCION_A":"Autorrenovarse durante mucho tiempo y diferenciarse hacia células especializadas.","OPCION_B":"Tejidos extraembrionarios, como los de la placenta.","OPCION_C":"Tipos celulares derivados de las tres capas embrionarias, pero no tejido placentario por sí solas.","OPCION_D":"Más restringido: genera varios tipos celulares relacionados con el tejido o linaje al que pertenece.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Tipos celulares derivados de las tres capas embrionarias, pero no tejido placentario por sí solas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"738–771"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"celulas madre y aplicaciones terapeuticas","DIFICULTAD":"medio","PREGUNTA":"¿Cómo suele ser el potencial de una célula madre multipotente adulta?","OPCION_A":"Tipos celulares derivados de las tres capas embrionarias, pero no tejido placentario por sí solas.","OPCION_B":"Autorrenovarse durante mucho tiempo y diferenciarse hacia células especializadas.","OPCION_C":"Más restringido: genera varios tipos celulares relacionados con el tejido o linaje al que pertenece.","OPCION_D":"Tejidos extraembrionarios, como los de la placenta.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Más restringido: genera varios tipos celulares relacionados con el tejido o linaje al que pertenece.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"738–771"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué busca la educación en salud además de transmitir información?","OPCION_A":"Que las personas desarrollen habilidades y adopten prácticas saludables de manera sostenida.","OPCION_B":"Que pueda comprender opciones y participar en decisiones que afectan su bienestar.","OPCION_C":"Que las personas participen y encuentren formas propias de mejorar la salud de su comunidad.","OPCION_D":"Que las personas y familias participen plenamente en una atención esencial y accesible.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Que las personas desarrollen habilidades y adopten prácticas saludables de manera sostenida.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–3"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"medio","PREGUNTA":"Si una comunidad aprende a decidir cómo cuidar su salud, ¿qué está ganando?","OPCION_A":"Participa activamente en su aprendizaje y en el cuidado colectivo de la salud.","OPCION_B":"Fortalece capacidades personales y comunitarias para mejorar condiciones de bienestar.","OPCION_C":"Ayuda a reconocer riesgos y a adoptar prácticas que disminuyan la posibilidad de enfermar.","OPCION_D":"Capacidad de autogestión y mayor control sobre los factores que afectan su bienestar.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Capacidad de autogestión y mayor control sobre los factores que afectan su bienestar.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–3"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué una charla aislada no basta para cambiar la salud de una población?","OPCION_A":"Porque aprender y ajustar conductas saludables requiere continuidad y reflexión, no una sola charla.","OPCION_B":"Porque los hábitos también dependen del entorno y de condiciones sociales; la educación debe acompañarse de acciones más amplias.","OPCION_C":"Para escuchar dudas y experiencias de la comunidad, además de compartir información.","OPCION_D":"Porque la posibilidad de practicarla depende también de recursos, costumbres y condiciones de vida.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Porque los hábitos también dependen del entorno y de condiciones sociales; la educación debe acompañarse de acciones más amplias.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–3"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"¿Con qué dos grandes tareas sanitarias se relaciona la educación en salud?","OPCION_A":"Fortalece capacidades personales y comunitarias para mejorar condiciones de bienestar.","OPCION_B":"Ayuda a reconocer riesgos y a adoptar prácticas que disminuyan la posibilidad de enfermar.","OPCION_C":"Pasa de la información a una habilidad y una práctica concreta.","OPCION_D":"Con la promoción de la salud y la prevención de enfermedades.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Con la promoción de la salud y la prevención de enfermedades.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–3"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué decir que salud es solo ''no estar enfermo'' resulta incompleto?","OPCION_A":"Porque el bienestar también incluye dimensiones psicológicas, sociales y la capacidad de adaptarse al entorno.","OPCION_B":"Porque todas las personas deben tener oportunidades y condiciones dignas para alcanzar bienestar.","OPCION_C":"Porque empleo y vivienda son determinantes sociales que condicionan cómo vive y enferma.","OPCION_D":"Porque el bienestar depende de condiciones sociales y ambientales, no solo de la atención médica.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque el bienestar también incluye dimensiones psicológicas, sociales y la capacidad de adaptarse al entorno.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"Dos barrios tienen distinta calidad de agua y vivienda. ¿Qué concepto ayuda a explicar sus diferencias de salud?","OPCION_A":"La interacción de factores biológicos, psicológicos y sociales.","OPCION_B":"La demográfica y la epidemiológica.","OPCION_C":"Los determinantes sociales y ambientales de la salud.","OPCION_D":"La física, la mental y la social.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los determinantes sociales y ambientales de la salud.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿Qué factores personales no modificables aparecen entre los determinantes de salud?","OPCION_A":"Entre otros, edad, sexo y herencia genética.","OPCION_B":"Políticas, distribución de la riqueza y educación.","OPCION_C":"Vivienda, alimentación y acceso a servicios.","OPCION_D":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Entre otros, edad, sexo y herencia genética.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿Qué significa buscar equidad en salud?","OPCION_A":"Actuar sobre esa diferencia para que ambos tengan una oportunidad similar de mantenerse sanos.","OPCION_B":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","OPCION_C":"Disminuye el peso relativo de infecciones y aumentan las enfermedades crónicas no transmisibles.","OPCION_D":"Políticas, distribución de la riqueza y educación.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"funciones de salud publica","DIFICULTAD":"facil","PREGUNTA":"Una ciudad analiza datos para detectar un brote. ¿Qué función de salud pública está realizando?","OPCION_A":"Promoción de la salud mediante un entorno favorable.","OPCION_B":"Participación comunitaria y gobernanza.","OPCION_C":"A la protección de la salud frente a riesgos ambientales.","OPCION_D":"Vigilancia y monitoreo de la salud.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Vigilancia y monitoreo de la salud.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"4–5"},{"MATERIA":"SALUD PUBLICA","TEMA":"funciones de salud publica","DIFICULTAD":"facil","PREGUNTA":"Controlar la calidad del agua potable, ¿a qué función de salud pública contribuye?","OPCION_A":"A la protección de la salud frente a riesgos ambientales.","OPCION_B":"Proteger y mejorar la salud de las poblaciones mediante esfuerzos organizados.","OPCION_C":"Promoción de la salud mediante un entorno favorable.","OPCION_D":"Vigilancia y monitoreo de la salud.","RESPUESTA_CORRECTA":"A","EXPLICACION":"A la protección de la salud frente a riesgos ambientales.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"4–5"},{"MATERIA":"SALUD PUBLICA","TEMA":"funciones de salud publica","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la población debe participar al definir problemas sanitarios?","OPCION_A":"Porque la participación comunitaria ayuda a reconocer necesidades y a tomar decisiones pertinentes.","OPCION_B":"Porque la consulta mira a una persona; la vigilancia identifica patrones y riesgos en grupos.","OPCION_C":"Porque proteger a una población exige coordinar información, recursos, servicios y decisiones colectivas.","OPCION_D":"Para reconocer riesgos, brotes y prioridades antes de decidir acciones.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque la participación comunitaria ayuda a reconocer necesidades y a tomar decisiones pertinentes.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"4–5"},{"MATERIA":"SALUD PUBLICA","TEMA":"funciones de salud publica","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia a una intervención poblacional de atender solo a un paciente?","OPCION_A":"Busca proteger o mejorar la salud de grupos y comunidades mediante acciones organizadas.","OPCION_B":"Controlar el agua elimina una exposición ambiental que podría causar enfermedad.","OPCION_C":"Vigilancia, protección, prevención, promoción y participación comunitaria.","OPCION_D":"Participación comunitaria y gobernanza.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Busca proteger o mejorar la salud de grupos y comunidades mediante acciones organizadas.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"4–5"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Vacunar para evitar que aparezca una enfermedad, ¿qué nivel de prevención es?","OPCION_A":"Prevención secundaria.","OPCION_B":"Prevención terciaria.","OPCION_C":"Prevención cuaternaria.","OPCION_D":"Prevención primaria.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Prevención primaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"5–19"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Un tamizaje detecta una enfermedad cuando aún no da síntomas. ¿Qué nivel de prevención es?","OPCION_A":"Prevención primaria.","OPCION_B":"Prevención terciaria.","OPCION_C":"Prevención cuaternaria.","OPCION_D":"Prevención secundaria: busca detección y tratamiento oportunos.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Prevención secundaria: busca detección y tratamiento oportunos.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"5–19"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"La rehabilitación después de un infarto, ¿qué nivel de prevención representa?","OPCION_A":"Prevención primaria.","OPCION_B":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","OPCION_C":"Prevención secundaria.","OPCION_D":"Prevención cuaternaria.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"5–19"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Evitar pruebas o tratamientos innecesarios que puedan dañar al paciente, ¿qué prevención es?","OPCION_A":"Prevención primaria.","OPCION_B":"Prevención secundaria.","OPCION_C":"Prevención terciaria.","OPCION_D":"Prevención cuaternaria.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Prevención cuaternaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"5–19"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"facil","PREGUNTA":"¿En qué se centra la promoción de la salud cuando mira más allá de la enfermedad?","OPCION_A":"En planes, programas y normas que guían los servicios de salud.","OPCION_B":"En crear condiciones y capacidades que favorezcan el bienestar de la población.","OPCION_C":"En los resultados obtenidos e interpretados, no en suposiciones ajenas al estudio.","OPCION_D":"En las condiciones en que las personas nacen, crecen, trabajan y envejecen.","RESPUESTA_CORRECTA":"B","EXPLICACION":"En crear condiciones y capacidades que favorezcan el bienestar de la población.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué pide la Carta de Ottawa respecto a las políticas públicas?","OPCION_A":"Que las personas participen y encuentren formas propias de mejorar la salud de su comunidad.","OPCION_B":"Que la salud también depende de condiciones del entorno, no solo de decisiones individuales.","OPCION_C":"Que se construyan políticas saludables y se consideren los efectos de las decisiones sobre la salud.","OPCION_D":"Qué se investigará, cuál es su base teórica y cómo se investigará.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Que se construyan políticas saludables y se consideren los efectos de las decisiones sobre la salud.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la participación comunitaria importa en la promoción?","OPCION_A":"Porque la promoción combina métodos complementarios para cambiar capacidades y condiciones de vida.","OPCION_B":"Porque la población identifica sus necesidades y ayuda a decidir y sostener las acciones.","OPCION_C":"Porque educación, vivienda, trabajo y otros sectores también determinan las oportunidades de estar sano.","OPCION_D":"Porque la consulta mira a una persona; la vigilancia identifica patrones y riesgos en grupos.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Porque la población identifica sus necesidades y ayuda a decidir y sostener las acciones.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué nivel de atención es normalmente el primer contacto de la persona con el sistema de salud?","OPCION_A":"El individuo, la familia y la comunidad.","OPCION_B":"Una barrera cultural de acceso.","OPCION_C":"La atención primaria de salud.","OPCION_D":"La primera permite llegar al servicio; la segunda mantiene el seguimiento a lo largo del tiempo.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La atención primaria de salud.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"Un centro de salud coordina una derivación y recibe la información de regreso. ¿Qué atributo de la atención primaria muestra?","OPCION_A":"Accesibilidad","OPCION_B":"Coordinación entre profesionales y niveles de atención.","OPCION_C":"Integralidad","OPCION_D":"Longitudinalidad","RESPUESTA_CORRECTA":"B","EXPLICACION":"Coordinación entre profesionales y niveles de atención.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué significa longitudinalidad en atención primaria?","OPCION_A":"Conectar acciones del equipo y de los distintos niveles para mantener la continuidad de la atención.","OPCION_B":"Accesibilidad, coordinación, integralidad y longitudinalidad.","OPCION_C":"Ser el primer contacto de la persona, la familia y la comunidad con el sistema de salud.","OPCION_D":"Acompañar a la persona o familia a lo largo del tiempo, no solo en una consulta aislada.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Acompañar a la persona o familia a lo largo del tiempo, no solo en una consulta aislada.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"medio","PREGUNTA":"Si un servicio aborda promoción, prevención, tratamiento y rehabilitación, ¿qué atributo demuestra?","OPCION_A":"Accesibilidad","OPCION_B":"Coordinación","OPCION_C":"Longitudinalidad","OPCION_D":"Integralidad de la atención.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Integralidad de la atención.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"factor de riesgo y salud comunitaria","DIFICULTAD":"facil","PREGUNTA":"¿Qué es un factor de riesgo?","OPCION_A":"El tabaquismo, porque puede reducirse o eliminarse mediante intervenciones y cambios de conducta.","OPCION_B":"Una característica o exposición que aumenta la probabilidad de una enfermedad o lesión, sin ser necesariamente una causa directa.","OPCION_C":"Las condiciones ambientales, los comportamientos y las exposiciones sociales.","OPCION_D":"La participación activa de la comunidad en reconocer problemas y buscar soluciones.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Una característica o exposición que aumenta la probabilidad de una enfermedad o lesión, sin ser necesariamente una causa directa.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"20–22"},{"MATERIA":"SALUD PUBLICA","TEMA":"factor de riesgo y salud comunitaria","DIFICULTAD":"facil","PREGUNTA":"Entre edad y tabaquismo, ¿cuál es un factor de riesgo modificable?","OPCION_A":"El tabaquismo, porque puede reducirse o eliminarse mediante intervenciones y cambios de conducta.","OPCION_B":"El tabaquismo; los antecedentes familiares no se pueden modificar.","OPCION_C":"Una característica o exposición que aumenta la probabilidad de una enfermedad o lesión, sin ser necesariamente una causa directa.","OPCION_D":"Las condiciones ambientales, los comportamientos y las exposiciones sociales.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El tabaquismo, porque puede reducirse o eliminarse mediante intervenciones y cambios de conducta.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"20–22"},{"MATERIA":"SALUD PUBLICA","TEMA":"factor de riesgo y salud comunitaria","DIFICULTAD":"facil","PREGUNTA":"¿Qué aporta la salud comunitaria a una intervención sanitaria?","OPCION_A":"La participación activa de la comunidad en reconocer problemas y buscar soluciones.","OPCION_B":"Las condiciones ambientales, los comportamientos y las exposiciones sociales.","OPCION_C":"Los sociales, los culturales y los ambientales.","OPCION_D":"Una característica o exposición que aumenta la probabilidad de una enfermedad o lesión, sin ser necesariamente una causa directa.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La participación activa de la comunidad en reconocer problemas y buscar soluciones.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"20–22"},{"MATERIA":"SALUD PUBLICA","TEMA":"factor de riesgo y salud comunitaria","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué no basta con culpar al individuo por todos sus riesgos?","OPCION_A":"Porque también influyen condiciones sociales, económicas y ambientales que limitan sus opciones.","OPCION_B":"Porque aumenta la probabilidad de enfermar, pero no determina por sí solo el resultado.","OPCION_C":"Porque crea condiciones que facilitan el bienestar de la comunidad.","OPCION_D":"Porque también incluye promoción, prevención, rehabilitación y seguimiento integral.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque también influyen condiciones sociales, económicas y ambientales que limitan sus opciones.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"20–22"},{"MATERIA":"SALUD PUBLICA","TEMA":"ods y cobertura sanitaria","DIFICULTAD":"facil","PREGUNTA":"¿Cuántos Objetivos de Desarrollo Sostenible reúne la Agenda 2030 descrita en el texto?","OPCION_A":"Hasta 2030.","OPCION_B":"Fortalecer la Atención Primaria en Salud.","OPCION_C":"Diecisiete objetivos.","OPCION_D":"Dimensiones sociales, económicas, ambientales y de gobernanza.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Diecisiete objetivos.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"6–9"},{"MATERIA":"SALUD PUBLICA","TEMA":"ods y cobertura sanitaria","DIFICULTAD":"facil","PREGUNTA":"¿Para qué sirven las metas e indicadores de los ODS?","OPCION_A":"Porque el agua y el saneamiento son determinantes de la salud.","OPCION_B":"Para fijar objetivos y seguir el progreso de forma medible.","OPCION_C":"Porque relacionan los problemas sanitarios con prioridades sociales, económicas y ambientales.","OPCION_D":"Porque el bienestar depende de condiciones sociales y ambientales, no solo de la atención médica.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Para fijar objetivos y seguir el progreso de forma medible.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"6–9"},{"MATERIA":"SALUD PUBLICA","TEMA":"ods y cobertura sanitaria","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la salud se relaciona con educación, ambiente y pobreza dentro de los ODS?","OPCION_A":"Porque relacionan los problemas sanitarios con prioridades sociales, económicas y ambientales.","OPCION_B":"Porque el agua y el saneamiento son determinantes de la salud.","OPCION_C":"Porque el bienestar depende de condiciones sociales y ambientales, no solo de la atención médica.","OPCION_D":"Para fijar objetivos y seguir el progreso de forma medible.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Porque el bienestar depende de condiciones sociales y ambientales, no solo de la atención médica.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"6–9"},{"MATERIA":"SALUD PUBLICA","TEMA":"ods y cobertura sanitaria","DIFICULTAD":"facil","PREGUNTA":"¿Qué persigue la cobertura sanitaria universal?","OPCION_A":"Que las personas puedan recibir servicios de salud necesarios sin quedar excluidas por barreras de acceso.","OPCION_B":"Que las personas participen y encuentren formas propias de mejorar la salud de su comunidad.","OPCION_C":"Que las personas desarrollen habilidades y adopten prácticas saludables de manera sostenida.","OPCION_D":"Que las personas y familias participen plenamente en una atención esencial y accesible.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Que las personas puedan recibir servicios de salud necesarios sin quedar excluidas por barreras de acceso.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"6–9"},{"MATERIA":"SALUD PUBLICA","TEMA":"salud en bolivia y modelo safci","DIFICULTAD":"facil","PREGUNTA":"¿Qué reconoce la Constitución boliviana sobre la salud según el material del curso?","OPCION_A":"El Sistema Único de Salud (SUS).","OPCION_B":"El Estado, con el fin de garantizar el derecho a la salud y reducir inequidades.","OPCION_C":"La articulación intercultural entre saberes ancestrales y biomedicina.","OPCION_D":"La reconoce como un derecho fundamental y una responsabilidad del Estado.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La reconoce como un derecho fundamental y una responsabilidad del Estado.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"10–14"},{"MATERIA":"SALUD PUBLICA","TEMA":"salud en bolivia y modelo safci","DIFICULTAD":"facil","PREGUNTA":"¿Qué significan las siglas SAFCI?","OPCION_A":"Evaluar y monitorizar su estado de salud.","OPCION_B":"Articular la atención con la familia y la comunidad, respetando saberes y prácticas culturales.","OPCION_C":"Salud Familiar Comunitaria Intercultural.","OPCION_D":"Participar en la planificación, vigilancia y evaluación de las acciones sanitarias.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Salud Familiar Comunitaria Intercultural.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"10–14"},{"MATERIA":"SALUD PUBLICA","TEMA":"salud en bolivia y modelo safci","DIFICULTAD":"facil","PREGUNTA":"¿Qué busca el enfoque intercultural del modelo SAFCI?","OPCION_A":"Trabajo cercano al territorio para prevenir enfermedades y promover hábitos saludables.","OPCION_B":"Articular la atención con la familia y la comunidad, respetando saberes y prácticas culturales.","OPCION_C":"Permite que comunidades y organizaciones ayuden a planificar y evaluar las acciones.","OPCION_D":"Participar en la planificación, vigilancia y evaluación de las acciones sanitarias.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Articular la atención con la familia y la comunidad, respetando saberes y prácticas culturales.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"10–14"},{"MATERIA":"SALUD PUBLICA","TEMA":"salud en bolivia y modelo safci","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué un programa de salud debe tener metas e indicadores?","OPCION_A":"Porque las condiciones de vida influyen en la salud y requieren respuestas entre sectores.","OPCION_B":"Para que sea pertinente y respete los saberes de la comunidad.","OPCION_C":"Para escuchar dudas y experiencias de la comunidad, además de compartir información.","OPCION_D":"Para evaluar si sus acciones mejoran la cobertura y los resultados sanitarios.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Para evaluar si sus acciones mejoran la cobertura y los resultados sanitarios.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"10–14"},{"MATERIA":"SALUD PUBLICA","TEMA":"epidemiologia social","DIFICULTAD":"facil","PREGUNTA":"¿Qué observa la epidemiología social además de contar casos de enfermedad?","OPCION_A":"La distribución de los casos y las posibles fuentes o vías de transmisión para orientar el control.","OPCION_B":"La regional o nacional, incluida la orientación de políticas públicas.","OPCION_C":"La respuesta social organizada frente a las condiciones de salud y enfermedad.","OPCION_D":"Las desigualdades, condiciones de vida y determinantes sociales que influyen en la salud de poblaciones.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Las desigualdades, condiciones de vida y determinantes sociales que influyen en la salud de poblaciones.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"32–39"},{"MATERIA":"SALUD PUBLICA","TEMA":"epidemiologia social","DIFICULTAD":"medio","PREGUNTA":"Si un barrio concentra más enfermedad por falta de agua segura, ¿qué pregunta haría la epidemiología social?","OPCION_A":"Cómo las desigualdades y condiciones sociales influyen en la salud de esos grupos.","OPCION_B":"Información recogida en el terreno junto con la vigilancia de los casos.","OPCION_C":"Explicar las causas de las desigualdades sanitarias.","OPCION_D":"Cómo las condiciones de vida y las decisiones colectivas contribuyen a esa diferencia.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Cómo las condiciones de vida y las decisiones colectivas contribuyen a esa diferencia.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"32–39"},{"MATERIA":"SALUD PUBLICA","TEMA":"epidemiologia social","DIFICULTAD":"facil","PREGUNTA":"¿Qué estudia la epidemiología de campo ante un brote?","OPCION_A":"Las desigualdades, condiciones de vida y determinantes sociales que influyen en la salud de poblaciones.","OPCION_B":"La regional o nacional, incluida la orientación de políticas públicas.","OPCION_C":"La respuesta social organizada frente a las condiciones de salud y enfermedad.","OPCION_D":"La distribución de los casos y las posibles fuentes o vías de transmisión para orientar el control.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La distribución de los casos y las posibles fuentes o vías de transmisión para orientar el control.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"32–39"},{"MATERIA":"SALUD PUBLICA","TEMA":"epidemiologia social","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué conviene comparar poblaciones y no solo describir a un paciente?","OPCION_A":"Porque permite reconocer patrones y factores que afectan la salud colectiva.","OPCION_B":"Porque puede pasar por alto pobreza, acceso a servicios y otras condiciones de vida.","OPCION_C":"Porque la salud poblacional reúne procesos de ambas dimensiones.","OPCION_D":"Para reconocer la distribución de un problema y generar hipótesis.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque permite reconocer patrones y factores que afectan la salud colectiva.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"32–39"},{"MATERIA":"SALUD PUBLICA","TEMA":"proceso de investigacion","DIFICULTAD":"medio","PREGUNTA":"Antes de recoger datos, ¿qué debes dejar claro en un proyecto de investigación?","OPCION_A":"Qué problema estudiarás, por qué importa y qué objetivos persigues.","OPCION_B":"Qué se investigará, cuál es su base teórica y cómo se investigará.","OPCION_C":"Que cada variable esté definida y los registros sean consistentes, sin valores mal codificados.","OPCION_D":"En la planificación.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Qué problema estudiarás, por qué importa y qué objetivos persigues.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"40–48"},{"MATERIA":"SALUD PUBLICA","TEMA":"proceso de investigacion","DIFICULTAD":"facil","PREGUNTA":"¿Para qué sirve el diseño de un estudio?","OPCION_A":"Para aportar conocimiento o ayudar a resolver el problema que motivó la investigación.","OPCION_B":"Para decidir cómo ordenar, presentar e interpretar los datos que se obtengan.","OPCION_C":"Para organizar cómo se obtendrán y analizarán datos capaces de responder la pregunta de investigación.","OPCION_D":"Porque los datos son la materia prima de los análisis y hallazgos posteriores.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Para organizar cómo se obtendrán y analizarán datos capaces de responder la pregunta de investigación.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"40–48"},{"MATERIA":"SALUD PUBLICA","TEMA":"proceso de investigacion","DIFICULTAD":"medio","PREGUNTA":"Si observas sin modificar las condiciones del fenómeno, ¿qué tipo general de estudio realizas?","OPCION_A":"Un estudio experimental.","OPCION_B":"El diseño metodológico.","OPCION_C":"Un estudio observacional.","OPCION_D":"La investigación cualitativa participativa o investigación-acción.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Un estudio observacional.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"40–48"},{"MATERIA":"SALUD PUBLICA","TEMA":"proceso de investigacion","DIFICULTAD":"medio","PREGUNTA":"Si el investigador interviene y compara resultados, ¿qué tipo general de estudio es?","OPCION_A":"Un estudio observacional.","OPCION_B":"Un estudio experimental.","OPCION_C":"El diseño metodológico.","OPCION_D":"La investigación cualitativa participativa o investigación-acción.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Un estudio experimental.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"40–48"},{"MATERIA":"SALUD PUBLICA","TEMA":"problema y objetivos de investigacion","DIFICULTAD":"facil","PREGUNTA":"¿Qué gana una investigación al delimitar bien su problema?","OPCION_A":"El método debe ser capaz de aportar datos para responder ese problema.","OPCION_B":"Una pregunta más precisa, viable y susceptible de estudiarse con datos.","OPCION_C":"Una actividad o resultado concreto relacionado con el problema principal.","OPCION_D":"El general expresa la meta principal; los específicos la descomponen en pasos concretos.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Una pregunta más precisa, viable y susceptible de estudiarse con datos.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"49–59"},{"MATERIA":"SALUD PUBLICA","TEMA":"problema y objetivos de investigacion","DIFICULTAD":"facil","PREGUNTA":"¿Cómo debería escribirse un objetivo de investigación para orientar el trabajo?","OPCION_A":"Sus variables o características mediante evidencia empírica.","OPCION_B":"Con una acción clara y un resultado observable o medible.","OPCION_C":"Perder su relación con el fenómeno general y su relevancia.","OPCION_D":"Concentrar el estudio en una parte clara y abordable de un tema más amplio.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Con una acción clara y un resultado observable o medible.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"49–59"},{"MATERIA":"SALUD PUBLICA","TEMA":"problema y objetivos de investigacion","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia hay entre objetivo general y objetivos específicos?","OPCION_A":"Una actividad o resultado concreto relacionado con el problema principal.","OPCION_B":"Una pregunta más precisa, viable y susceptible de estudiarse con datos.","OPCION_C":"El método debe ser capaz de aportar datos para responder ese problema.","OPCION_D":"El general expresa la meta principal; los específicos la descomponen en pasos concretos.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El general expresa la meta principal; los específicos la descomponen en pasos concretos.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"49–59"},{"MATERIA":"SALUD PUBLICA","TEMA":"problema y objetivos de investigacion","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué los objetivos deben corresponder al problema planteado?","OPCION_A":"Porque falta concretar qué se estudiará, en quiénes, dónde y con qué alcance.","OPCION_B":"Porque orienta de forma directa qué datos habrá que buscar para responderla.","OPCION_C":"Porque cada objetivo debe aportar evidencia para responder la pregunta central.","OPCION_D":"Porque su duración debe permitir que los hallazgos sirvan para tomar decisiones a tiempo.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Porque cada objetivo debe aportar evidencia para responder la pregunta central.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"49–59"},{"MATERIA":"SALUD PUBLICA","TEMA":"marco teorico e hipotesis","DIFICULTAD":"facil","PREGUNTA":"¿Para qué revisas literatura antes de formular una hipótesis?","OPCION_A":"Para situarlo en el conocimiento existente y orientar su explicación y análisis.","OPCION_B":"Para conocer lo que ya se sabe y fundamentar la relación que vas a estudiar.","OPCION_C":"Para reconocer conceptos, antecedentes y relaciones que fundamenten el estudio.","OPCION_D":"Para poder definir variables y comprobarla con datos sin ambigüedad.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Para conocer lo que ya se sabe y fundamentar la relación que vas a estudiar.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"60–72"},{"MATERIA":"SALUD PUBLICA","TEMA":"marco teorico e hipotesis","DIFICULTAD":"facil","PREGUNTA":"¿Qué es una hipótesis de investigación?","OPCION_A":"Un aspecto de la variable que permite examinarla y medirla con mayor precisión.","OPCION_B":"Una explicación o relación tentativa que puede contrastarse con observaciones.","OPCION_C":"La exposición al tabaquismo; el resultado de salud sería la variable dependiente.","OPCION_D":"Las que se relacionen con el problema y los objetivos del estudio.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Una explicación o relación tentativa que puede contrastarse con observaciones.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"60–72"},{"MATERIA":"SALUD PUBLICA","TEMA":"marco teorico e hipotesis","DIFICULTAD":"medio","PREGUNTA":"Si planteas que el tabaquismo influye en un resultado de salud, ¿cuál suele ser la variable independiente?","OPCION_A":"La independiente; el resultado se considera dependiente.","OPCION_B":"La exposición al tabaquismo; el resultado de salud sería la variable dependiente.","OPCION_C":"Un aspecto de la variable que permite examinarla y medirla con mayor precisión.","OPCION_D":"Una explicación o relación tentativa que puede contrastarse con observaciones.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La exposición al tabaquismo; el resultado de salud sería la variable dependiente.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"60–72"},{"MATERIA":"SALUD PUBLICA","TEMA":"marco teorico e hipotesis","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué una hipótesis debe usar conceptos claros?","OPCION_A":"Para relacionarlo con manifestaciones observables o medibles.","OPCION_B":"Para conocer lo que ya se sabe y fundamentar la relación que vas a estudiar.","OPCION_C":"Para poder definir variables y comprobarla con datos sin ambigüedad.","OPCION_D":"Para reconocer conceptos, antecedentes y relaciones que fundamenten el estudio.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Para poder definir variables y comprobarla con datos sin ambigüedad.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"60–72"},{"MATERIA":"SALUD PUBLICA","TEMA":"variables y medicion","DIFICULTAD":"facil","PREGUNTA":"¿Qué es una variable dentro de una investigación?","OPCION_A":"Un elemento que puede influir indirectamente en la relación entre la independiente y la dependiente.","OPCION_B":"La variable dependiente.","OPCION_C":"La forma de estudio: en grupo o individualmente.","OPCION_D":"Una característica de las unidades de estudio que puede tomar distintos valores o categorías.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Una característica de las unidades de estudio que puede tomar distintos valores o categorías.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"72–76"},{"MATERIA":"SALUD PUBLICA","TEMA":"variables y medicion","DIFICULTAD":"facil","PREGUNTA":"¿La ocupación se registra como variable cualitativa o cuantitativa?","OPCION_A":"Cualitativa: clasifica a las personas en categorías.","OPCION_B":"Cuantitativa; expresa una magnitud numérica.","OPCION_C":"Como categoría; es una variable cualitativa.","OPCION_D":"Puede tomar valores intermedios dentro de un intervalo.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Cualitativa: clasifica a las personas en categorías.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"72–76"},{"MATERIA":"SALUD PUBLICA","TEMA":"variables y medicion","DIFICULTAD":"facil","PREGUNTA":"¿La talla medida en centímetros es cualitativa o cuantitativa?","OPCION_A":"Cualitativa: clasifica a las personas en categorías.","OPCION_B":"Como categoría; es una variable cualitativa.","OPCION_C":"Cuantitativa; expresa una magnitud numérica.","OPCION_D":"Continua; puede medirse en metros, centímetros y subdivisiones menores.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Cuantitativa; expresa una magnitud numérica.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"72–76"},{"MATERIA":"SALUD PUBLICA","TEMA":"variables y medicion","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué conviene definir cómo medirás cada variable antes de recoger datos?","OPCION_A":"Para que todos los registros se hagan con el mismo criterio y puedan compararse.","OPCION_B":"Porque su magnitud se expresa mediante una medida numérica.","OPCION_C":"Porque se cuentan hijos completos, no fracciones de un hijo.","OPCION_D":"Porque toma valores distintos entre personas o en diferentes momentos.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Para que todos los registros se hagan con el mismo criterio y puedan compararse.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"72–76"},{"MATERIA":"SALUD PUBLICA","TEMA":"estadistica descriptiva","DIFICULTAD":"facil","PREGUNTA":"¿Qué hace la estadística descriptiva con un conjunto de datos?","OPCION_A":"Una parte de la población seleccionada para observarla o medirla.","OPCION_B":"Una muestra seleccionada con técnicas adecuadas.","OPCION_C":"Los organiza y resume con tablas, gráficos y medidas numéricas.","OPCION_D":"El conjunto de unidades sobre las que se quiere conocer una característica.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los organiza y resume con tablas, gráficos y medidas numéricas.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"85–94"},{"MATERIA":"SALUD PUBLICA","TEMA":"estadistica descriptiva","DIFICULTAD":"medio","PREGUNTA":"Si quieres sacar conclusiones sobre una población usando una muestra, ¿qué rama de la estadística utilizas?","OPCION_A":"Estadística descriptiva.","OPCION_B":"Ordinal, porque las categorías tienen un orden.","OPCION_C":"Cuantitativa discreta.","OPCION_D":"Estadística inferencial.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Estadística inferencial.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"85–94"},{"MATERIA":"SALUD PUBLICA","TEMA":"estadistica descriptiva","DIFICULTAD":"facil","PREGUNTA":"¿Qué es la población de un estudio?","OPCION_A":"El conjunto de unidades sobre las que se quiere conocer una característica.","OPCION_B":"El elemento concreto que se investiga: persona, grupo, objeto o acontecimiento.","OPCION_C":"Una muestra seleccionada con técnicas adecuadas.","OPCION_D":"El parámetro describe a la población; el estadígrafo describe a la muestra.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El conjunto de unidades sobre las que se quiere conocer una característica.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"85–94"},{"MATERIA":"SALUD PUBLICA","TEMA":"estadistica descriptiva","DIFICULTAD":"facil","PREGUNTA":"¿Qué es una muestra?","OPCION_A":"Los organiza y resume con tablas, gráficos y medidas numéricas.","OPCION_B":"El conjunto de unidades sobre las que se quiere conocer una característica.","OPCION_C":"El parámetro describe a la población; el estadígrafo describe a la muestra.","OPCION_D":"Una parte de la población seleccionada para observarla o medirla.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Una parte de la población seleccionada para observarla o medirla.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"85–94"},{"MATERIA":"SALUD PUBLICA","TEMA":"muestreo","DIFICULTAD":"medio","PREGUNTA":"Si todos los integrantes tienen una probabilidad conocida de ser elegidos, ¿qué tipo de muestreo usas?","OPCION_A":"Dividiendo N entre n.","OPCION_B":"Muestreo probabilístico.","OPCION_C":"Muestreo por conglomerados.","OPCION_D":"Muestreo estratificado.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Muestreo probabilístico.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"95–108"},{"MATERIA":"SALUD PUBLICA","TEMA":"muestreo","DIFICULTAD":"facil","PREGUNTA":"Divides la población en grupos y seleccionas personas de cada uno. ¿Qué muestreo es?","OPCION_A":"Dividiendo N entre n.","OPCION_B":"Muestreo estratificado.","OPCION_C":"Muestreo por conglomerados.","OPCION_D":"Muestreo probabilístico.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Muestreo estratificado.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"95–108"},{"MATERIA":"SALUD PUBLICA","TEMA":"muestreo","DIFICULTAD":"facil","PREGUNTA":"Eliges grupos completos, como aulas, y estudias a sus integrantes. ¿Qué muestreo es?","OPCION_A":"Muestreo intencional.","OPCION_B":"Muestreo estratificado.","OPCION_C":"Muestreo probabilístico.","OPCION_D":"Muestreo por conglomerados.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Muestreo por conglomerados.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"95–108"},{"MATERIA":"SALUD PUBLICA","TEMA":"muestreo","DIFICULTAD":"medio","PREGUNTA":"Si los seleccionados no representan bien a la población, ¿qué problema aparece?","OPCION_A":"Error de cobertura: esas personas no tienen posibilidad de ser seleccionadas.","OPCION_B":"Sesgo de selección o de cobertura, que puede distorsionar los resultados.","OPCION_C":"Muestreo por conglomerados.","OPCION_D":"Dividiendo N entre n.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Sesgo de selección o de cobertura, que puede distorsionar los resultados.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"95–108"}]'::jsonb) AS p("MATERIA" text, "TEMA" text, "DIFICULTAD" text, "PREGUNTA" text, "OPCION_A" text, "OPCION_B" text, "OPCION_C" text, "OPCION_D" text, "RESPUESTA_CORRECTA" text, "EXPLICACION" text, "FUENTE" text, "PAGINAS_PDF" text)
), missing AS (
  SELECT p.* FROM payload p
  WHERE NOT EXISTS (
    SELECT 1 FROM public.banco_preguntas b
    WHERE b."MATERIA" = p."MATERIA" AND lower(b."PREGUNTA") = lower(p."PREGUNTA")
  )
), numbered AS (
  SELECT (SELECT coalesce(max(id), 0) FROM public.banco_preguntas) + row_number() OVER (ORDER BY "MATERIA", "TEMA", "PREGUNTA") AS id, m.*
  FROM missing m
)
INSERT INTO public.banco_preguntas (id, "MATERIA", "TEMA", "DIFICULTAD", "PREGUNTA", "OPCION_A", "OPCION_B", "OPCION_C", "OPCION_D", "RESPUESTA_CORRECTA", "EXPLICACION", "FUENTE", "PAGINAS_PDF")
SELECT n.id, n."MATERIA", n."TEMA", n."DIFICULTAD", n."PREGUNTA", n."OPCION_A", n."OPCION_B", n."OPCION_C", n."OPCION_D", n."RESPUESTA_CORRECTA", n."EXPLICACION", n."FUENTE", n."PAGINAS_PDF" FROM numbered n;
COMMIT;

-- Banco de preguntas oficial, lote 17. Reejecutable sin duplicados.
