ALTER TABLE public.banco_preguntas ADD COLUMN IF NOT EXISTS "PAGINAS_PDF" text;
WITH payload AS (
  SELECT * FROM jsonb_to_recordset('[{"MATERIA":"SALUD PUBLICA","TEMA":"frecuencias y graficos","DIFICULTAD":"facil","PREGUNTA":"¿Qué expresa la frecuencia absoluta de una categoría?","OPCION_A":"Cuántas observaciones, o qué proporción, se han reunido hasta cierto valor o intervalo.","OPCION_B":"Clasificar la variable y construir su tabla de frecuencias.","OPCION_C":"Cuántos casos se encuentran hasta cierto valor o intervalo.","OPCION_D":"Cuántas observaciones pertenecen a esa categoría.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Cuántas observaciones pertenecen a esa categoría.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"109–139"},{"MATERIA":"SALUD PUBLICA","TEMA":"frecuencias y graficos","DIFICULTAD":"facil","PREGUNTA":"¿Qué expresa la frecuencia relativa?","OPCION_A":"La proporción o porcentaje del total que corresponde a una categoría.","OPCION_B":"Las ordenas por categorías o valores y cuentas cuántas hay de cada uno.","OPCION_C":"La distancia entre sus límites superior e inferior.","OPCION_D":"La parte del total correspondiente a una categoría.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La proporción o porcentaje del total que corresponde a una categoría.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"109–139"},{"MATERIA":"SALUD PUBLICA","TEMA":"frecuencias y graficos","DIFICULTAD":"medio","PREGUNTA":"Si quieres mostrar la distribución de una variable cuantitativa agrupada en intervalos, ¿qué gráfico usarías?","OPCION_A":"Un histograma.","OPCION_B":"Un diagrama de barras.","OPCION_C":"El rango es 30.","OPCION_D":"Una ojiva o curva de frecuencia acumulada.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Un histograma.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"109–139"},{"MATERIA":"SALUD PUBLICA","TEMA":"frecuencias y graficos","DIFICULTAD":"facil","PREGUNTA":"¿Qué muestra una frecuencia acumulada?","OPCION_A":"Cuántas observaciones pertenecen a esa categoría.","OPCION_B":"Clasificar la variable y construir su tabla de frecuencias.","OPCION_C":"Cuántas observaciones, o qué proporción, se han reunido hasta cierto valor o intervalo.","OPCION_D":"Cuántos casos se encuentran hasta cierto valor o intervalo.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Cuántas observaciones, o qué proporción, se han reunido hasta cierto valor o intervalo.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"109–139"},{"MATERIA":"SALUD PUBLICA","TEMA":"medidas de tendencia central","DIFICULTAD":"facil","PREGUNTA":"¿Cómo calculas la media aritmética de varios valores?","OPCION_A":"Puede desplazarse hacia arriba, aunque los demás datos no cambien.","OPCION_B":"Sumas los valores y divides entre el número de observaciones.","OPCION_C":"Promedias los dos valores centrales de la lista ordenada.","OPCION_D":"Hay dos modas; la distribución es bimodal.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Sumas los valores y divides entre el número de observaciones.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"145–160"},{"MATERIA":"SALUD PUBLICA","TEMA":"medidas de tendencia central","DIFICULTAD":"facil","PREGUNTA":"Ordenas las edades de menor a mayor. ¿Qué medida ocupa el centro de la lista?","OPCION_A":"La moda.","OPCION_B":"La media aritmética.","OPCION_C":"La mitad, 50 % a cada lado.","OPCION_D":"La mediana.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La mediana.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"145–160"},{"MATERIA":"SALUD PUBLICA","TEMA":"medidas de tendencia central","DIFICULTAD":"facil","PREGUNTA":"En una lista de respuestas, ¿cómo llamas al valor que aparece más veces?","OPCION_A":"Moda.","OPCION_B":"Azul.","OPCION_C":"Buscando el intervalo con mayor frecuencia absoluta.","OPCION_D":"Ordenarlos de menor a mayor.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Moda.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"145–160"},{"MATERIA":"SALUD PUBLICA","TEMA":"medidas de tendencia central","DIFICULTAD":"medio","PREGUNTA":"Si unos pocos valores son extremadamente altos, ¿qué medida central suele resistir mejor su efecto?","OPCION_A":"La moda.","OPCION_B":"La mediana.","OPCION_C":"La media aritmética.","OPCION_D":"La mitad, 50 % a cada lado.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La mediana.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"145–160"},{"MATERIA":"SALUD PUBLICA","TEMA":"medidas de posicion","DIFICULTAD":"facil","PREGUNTA":"¿En cuántas partes dividen los cuartiles un conjunto de datos ordenados?","OPCION_A":"En diez partes.","OPCION_B":"En la pestaña Datos.","OPCION_C":"En Vista de datos.","OPCION_D":"En cuatro partes.","RESPUESTA_CORRECTA":"D","EXPLICACION":"En cuatro partes.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"161–170"},{"MATERIA":"SALUD PUBLICA","TEMA":"medidas de posicion","DIFICULTAD":"facil","PREGUNTA":"¿Qué representa el percentil 75?","OPCION_A":"El segundo cuartil, Q2.","OPCION_B":"El primer cuartil, Q1.","OPCION_C":"Un valor por debajo del cual se encuentra aproximadamente el 75 % de las observaciones.","OPCION_D":"La mediana.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Un valor por debajo del cual se encuentra aproximadamente el 75 % de las observaciones.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"161–170"},{"MATERIA":"SALUD PUBLICA","TEMA":"medidas de posicion","DIFICULTAD":"facil","PREGUNTA":"¿En cuántas partes dividen los deciles los datos ordenados?","OPCION_A":"En diez partes.","OPCION_B":"En cuatro partes.","OPCION_C":"En la pestaña Datos.","OPCION_D":"En Vista de datos.","RESPUESTA_CORRECTA":"A","EXPLICACION":"En diez partes.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"161–170"},{"MATERIA":"SALUD PUBLICA","TEMA":"medidas de posicion","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué primero debes ordenar los datos antes de ubicar un cuartil?","OPCION_A":"Porque las medidas de posición dependen del lugar que ocupa cada valor en la distribución.","OPCION_B":"Porque las condiciones de vida influyen en la salud y requieren respuestas entre sectores.","OPCION_C":"Porque las desviaciones usadas para calcularla se elevan al cuadrado.","OPCION_D":"Para que todos los registros se hagan con el mismo criterio y puedan compararse.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque las medidas de posición dependen del lugar que ocupa cada valor en la distribución.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"161–170"},{"MATERIA":"SALUD PUBLICA","TEMA":"dispersion y forma de los datos","DIFICULTAD":"facil","PREGUNTA":"Dos grupos tienen la misma media, pero uno varía mucho más. ¿Qué clase de medida necesitas para distinguirlos?","OPCION_A":"La diferencia entre cada dato y la media, elevada al cuadrado.","OPCION_B":"Una medida de dispersión, como la desviación estándar.","OPCION_C":"La diferencia entre el valor máximo y el mínimo.","OPCION_D":"La dispersión de la mitad central de los datos.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Una medida de dispersión, como la desviación estándar.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"171–190"},{"MATERIA":"SALUD PUBLICA","TEMA":"dispersion y forma de los datos","DIFICULTAD":"facil","PREGUNTA":"¿Qué es el rango de un conjunto de datos?","OPCION_A":"La diferencia entre el valor máximo y el mínimo.","OPCION_B":"La diferencia entre cada dato y la media, elevada al cuadrado.","OPCION_C":"La dispersión de la mitad central de los datos.","OPCION_D":"Una distribución aproximadamente simétrica.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La diferencia entre el valor máximo y el mínimo.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"171–190"},{"MATERIA":"SALUD PUBLICA","TEMA":"dispersion y forma de los datos","DIFICULTAD":"facil","PREGUNTA":"¿Qué mide la desviación estándar?","OPCION_A":"Cuánto se alejan típicamente los valores de la media.","OPCION_B":"Mayor dispersión alrededor de la media.","OPCION_C":"Solo usa los dos valores extremos e ignora cómo se distribuyen los demás.","OPCION_D":"Tomando su raíz cuadrada positiva.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Cuánto se alejan típicamente los valores de la media.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"171–190"},{"MATERIA":"SALUD PUBLICA","TEMA":"dispersion y forma de los datos","DIFICULTAD":"medio","PREGUNTA":"Si una distribución tiene una cola más larga hacia un lado, ¿qué propiedad describes?","OPCION_A":"Negativo, o sesgo hacia la izquierda.","OPCION_B":"Platicúrtica.","OPCION_C":"Su asimetría o sesgo.","OPCION_D":"Restando Q1 de Q3.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Su asimetría o sesgo.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"171–190"},{"MATERIA":"SALUD PUBLICA","TEMA":"analisis de datos en excel y spss","DIFICULTAD":"facil","PREGUNTA":"Antes de pedir resultados estadísticos a un programa, ¿qué debes revisar en tu tabla de datos?","OPCION_A":"Que cada variable esté definida y los registros sean consistentes, sin valores mal codificados.","OPCION_B":"Qué problema estudiarás, por qué importa y qué objetivos persigues.","OPCION_C":"Interpretarlo en relación con la pregunta de investigación; el programa calcula, pero no explica por sí solo el problema.","OPCION_D":"Revisar los datos y la definición de la variable antes de interpretar el resultado.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Que cada variable esté definida y los registros sean consistentes, sin valores mal codificados.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"191–226"},{"MATERIA":"SALUD PUBLICA","TEMA":"analisis de datos en excel y spss","DIFICULTAD":"facil","PREGUNTA":"¿Para qué puede servir la herramienta de estadística descriptiva de Excel?","OPCION_A":"Para mostrar una descripción comprensible de la variable en los resultados.","OPCION_B":"Cuando el rango elegido incluye el nombre de la variable en su primera fila.","OPCION_C":"Para resumir datos con medidas como media, mediana y dispersión.","OPCION_D":"Para que no distorsione frecuencias y cálculos estadísticos.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Para resumir datos con medidas como media, mediana y dispersión.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"191–226"},{"MATERIA":"SALUD PUBLICA","TEMA":"analisis de datos en excel y spss","DIFICULTAD":"dificil","PREGUNTA":"En SPSS, ¿por qué conviene asignar etiquetas a las categorías de una variable?","OPCION_A":"Para mostrar una descripción comprensible de la variable en los resultados.","OPCION_B":"Cuando el rango elegido incluye el nombre de la variable en su primera fila.","OPCION_C":"Para interpretar las salidas sin depender de códigos numéricos poco claros.","OPCION_D":"Porque los cálculos se basan en respuestas disponibles y deben interpretarse conociendo cuántos faltan.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Para interpretar las salidas sin depender de códigos numéricos poco claros.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"191–226"},{"MATERIA":"SALUD PUBLICA","TEMA":"analisis de datos en excel y spss","DIFICULTAD":"facil","PREGUNTA":"¿Qué debes hacer después de obtener una tabla o un gráfico de cualquier programa?","OPCION_A":"Revisar los datos y la definición de la variable antes de interpretar el resultado.","OPCION_B":"Conteos, porcentajes y, cuando corresponde, porcentajes acumulados.","OPCION_C":"Variables cuantitativas, cuando esas medidas son apropiadas para el análisis.","OPCION_D":"Interpretarlo en relación con la pregunta de investigación; el programa calcula, pero no explica por sí solo el problema.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Interpretarlo en relación con la pregunta de investigación; el programa calcula, pero no explica por sí solo el problema.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"191–226"}]'::jsonb) AS p("MATERIA" text, "TEMA" text, "DIFICULTAD" text, "PREGUNTA" text, "OPCION_A" text, "OPCION_B" text, "OPCION_C" text, "OPCION_D" text, "RESPUESTA_CORRECTA" text, "EXPLICACION" text, "FUENTE" text, "PAGINAS_PDF" text)
), missing AS (
  SELECT p.* FROM payload p
  WHERE NOT EXISTS (
    SELECT 1 FROM public.banco_preguntas b
    WHERE b."MATERIA" = p."MATERIA" AND lower(b."PREGUNTA") = lower(p."PREGUNTA")
  )
), numbered AS (
  SELECT (SELECT coalesce(max(id), 0) FROM public.banco_preguntas) + row_number() OVER (ORDER BY "MATERIA", "TEMA", "PREGUNTA") AS id, m.*
  FROM missing m
)
INSERT INTO public.banco_preguntas (id, "MATERIA", "TEMA", "DIFICULTAD", "PREGUNTA", "OPCION_A", "OPCION_B", "OPCION_C", "OPCION_D", "RESPUESTA_CORRECTA", "EXPLICACION", "FUENTE", "PAGINAS_PDF")
SELECT n.id, n."MATERIA", n."TEMA", n."DIFICULTAD", n."PREGUNTA", n."OPCION_A", n."OPCION_B", n."OPCION_C", n."OPCION_D", n."RESPUESTA_CORRECTA", n."EXPLICACION", n."FUENTE", n."PAGINAS_PDF" FROM numbered n;
COMMIT;
